/*
 ==============================================================================
 TAREA 1 - TALLER V - GPIO, TIMERS Y EXTI
 ==============================================================================

 DESCRIPCION DEL HARDWARE UTILIZADO

 - Tarjeta NUCLEO-F411RE (microcontrolador STM32F411RE, nucleo ARM Cortex-M4).
   Se usa el reloj interno HSI de 16 MHz. El boton negro de la tarjeta (RESET)
   reinicia el programa en cualquier momento.

 - Display de 7 segmentos de 4 digitos KEM-5641-BSR (anodo comun).
   Los 8 LEDs de cada digito (a, b, c, d, e, f, g, dp) estan unidos entre los
   4 digitos, y cada digito tiene su propio anodo comun. Por ser anodo comun,
   un segmento se ENCIENDE cuando su pin del STM32 esta en 0 (bajo).
   Cada segmento lleva una resistencia de 220-330 ohm para limitar la corriente.

 - 4 transistores PNP (2N3906 / 2N2907), uno por digito.
   Emisor a 3.3 V, colector al anodo comun del digito, y base al STM32 por
   medio de una resistencia de 1 kohm. El digito se ENCIENDE cuando el pin
   de la base esta en 0 (bajo).

 - 2 photo-interruptores (fotocompuertas de ranura). Cada uno tiene un LED
   infrarrojo (emisor) y un fototransistor (sensor) separados por una ranura.
   La salida del fototransistor tiene una resistencia de pull-up de 10 kohm a
   3.3 V. Al pasar un objeto por la ranura se tapa la luz y la salida cambia
   de nivel, lo que genera una interrupcion externa (EXTI).

 - 1 LED de estado conectado a PH1 (con su resistencia), que parpadea para
   indicar que el microcontrolador esta funcionando.

 CONEXIONES

  Segmentos del display:          Digitos (base de los PNP):
  a  (pin 11) = PB12              digito 1 (pin 12) = PC5  (unidades de mil)
  b  (pin 7)  = PA12              digito 2 (pin 9)  = PC6  (centenas)
  c  (pin 4)  = PC11              digito 3 (pin 8)  = PC2  (decenas)
  d  (pin 2)  = PC10              digito 4 (pin 6)  = PB7  (unidades)
  e  (pin 1)  = PC12
  f  (pin 10) = PA11
  g  (pin 5)  = PD2
  dp (pin 3)  = sin conectar

  Sensores:
  PC3 = photo-interruptor que SUBE el contador (EXTI3, flanco de subida)
  PA0 = photo-interruptor que BAJA el contador (EXTI0, flanco de bajada)

  LED de estado:
  PH1

 COMO FUNCIONA EL SISTEMA

 Se usan 4 interrupciones. Las interrupciones hacen lo minimo posible:
 cada IRQHandler verifica y limpia la bandera del periferico y llama a su
 callback, y el callback solo levanta una bandera (variable en 1) para
 avisar al while(1) del main. El trabajo de verdad se hace en el while(1),
 que revisa las banderas una por una, las baja y ejecuta la tarea:

 1. TIM2 (blinky): el timer genera una interrupcion cada 500 ms y levanta
    bandera_blinky. En el while se invierte el estado de PH1, asi el LED de
    estado parpadea a 1 Hz.

 2. TIM3 (refresco del display): el timer genera una interrupcion cada 1 ms
    y levanta bandera_display. En el while se cuenta 1 ms (para el
    antirrebote) y se hace el multiplexado (efecto POV): se apagan todos los
    digitos, se calcula la cifra que corresponde al siguiente digito, se
    encienden los segmentos de esa cifra y por ultimo se enciende solo ese
    digito. Como cada digito se enciende cada 4 ms (250 veces por segundo),
    el ojo ve los 4 digitos encendidos al mismo tiempo. Apagar los digitos
    antes de cambiar los segmentos evita el efecto "fantasma".

 3. EXTI3 (PC3, flanco de subida): cuando el photo-interruptor detecta un
    objeto se levanta bandera_sube. En el while se suma 1 al contador.

 4. EXTI0 (PA0, flanco de bajada): cuando el photo-interruptor detecta un
    objeto se levanta bandera_baja. En el while se resta 1 al contador.

 Los sensores tienen un antirrebote de 50 ms: si llega otra interrupcion del
 mismo sensor antes de 50 ms, se ignora.

 El contador es de tipo uint16_t (0 a 65535) y no tiene proteccion: al restar
 1 a 0 pasa a 65535 y al sumar 1 a 65535 vuelve a 0. Como el display solo
 tiene 4 digitos, se muestran las 4 ultimas cifras (65535 se ve como 5535).
 ==============================================================================
*/

#include <stdint.h>
#include "stm32f411xe.h"
#include "stm32f4xx.h"

uint8_t estado_actual = 0;              // Digito que se enciende en este turno (0 a 3)
uint8_t cifra = 0;                      // Cifra (0 a 9) que se dibuja en el digito actual

uint16_t contador = 0;                  // Contador (0 a 65535)
uint32_t milisegundos = 0;              // Milisegundos transcurridos (se cuentan con la bandera de TIM3)
uint32_t ultimo_subir = 0;              // Ultima vez que se acepto el sensor de PC3 (antirrebote)
uint32_t ultimo_bajar = 0;              // Ultima vez que se acepto el sensor de PA0 (antirrebote)

// Banderas que levantan las interrupciones (volatile porque las cambian las interrupciones)
volatile uint8_t bandera_blinky = 0;    // TIM2: toca invertir el LED de estado
volatile uint8_t bandera_display = 0;   // TIM3: toca refrescar el siguiente digito
volatile uint8_t bandera_sube = 0;      // EXTI3: el sensor de PC3 detecto un objeto
volatile uint8_t bandera_baja = 0;      // EXTI0: el sensor de PA0 detecto un objeto

void callback_blinky(void);
void callback_display(void);
void callback_sensor_sube(void);
void callback_sensor_baja(void);

int main(void)
{

    /*
     HABILITAR RELOJES
     GPIOA, GPIOB, GPIOC, GPIOD, GPIOH (RCC->AHB1ENR)
     TIM2, TIM3 (RCC->APB1ENR)
     SYSCFG (RCC->APB2ENR)
    */
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN; // Habilitar señal de reloj para GPIOA (Bit 0)
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOBEN; // Habilitar señal de reloj para GPIOB (Bit 1)
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOCEN; // Habilitar señal de reloj para GPIOC (Bit 2)
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIODEN; // Habilitar señal de reloj para GPIOD (Bit 3)
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOHEN; // Habilitar señal de reloj para GPIOH (Bit 7)
    RCC->APB1ENR |= RCC_APB1ENR_TIM2EN;  // Habilitar señal de reloj para TIM2 (Bit 0)
    RCC->APB1ENR |= RCC_APB1ENR_TIM3EN;  // Habilitar señal de reloj para TIM3 (Bit 1)
    RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN; // Habilitar señal de reloj para SYSCFG (Bit 14)

    /* 
     CONFIGURAR LOS PINES DE LOS SEGMENTOS COMO SALIDA
     */

    /*
    a (PB12)
    */
     GPIOB->MODER    &= ~ (GPIO_MODER_MODE12); // Limpiar bits de modo para PB12
     GPIOB->MODER    |=  (GPIO_MODER_MODE12_0); // Configurar PB12 como salida (general purpose output)
     GPIOB->OTYPER   &= ~ GPIO_OTYPER_OT12; // Configurar PB12 como salida push-pull
     GPIOB->OSPEEDR  &= ~ (GPIO_OSPEEDR_OSPEED12); // Configurar PB12 como baja velocidad
     GPIOB->PUPDR    &= ~ (GPIO_PUPDR_PUPD12); // Configurar PB12 sin pull-up/pull-down
     GPIOB->ODR      |= (GPIO_ODR_OD12); // Inicializar PB12 en alto (segmento apagado)

    /*
    b (PA12)
    */
     GPIOA->MODER    &= ~ (GPIO_MODER_MODE12); // Limpiar bits de modo para PA12
     GPIOA->MODER    |=  (GPIO_MODER_MODE12_0); // Configurar PA12 como salida (general purpose output)
     GPIOA->OTYPER   &= ~ GPIO_OTYPER_OT12; // Configurar PA12 como salida push-pull
     GPIOA->OSPEEDR  &= ~ (GPIO_OSPEEDR_OSPEED12); // Configurar PA12 como baja velocidad
     GPIOA->PUPDR    &= ~ (GPIO_PUPDR_PUPD12); // Configurar PA12 sin pull-up/pull-down
     GPIOA->ODR      |= (GPIO_ODR_OD12); // Inicializar PA12 en alto (segmento apagado)

    /*
    c (PC11)
    */
     GPIOC->MODER    &= ~ (GPIO_MODER_MODE11); // Limpiar bits de modo para PC11
     GPIOC->MODER    |=  (GPIO_MODER_MODE11_0); // Configurar PC11 como salida (general purpose output)
     GPIOC->OTYPER   &= ~ GPIO_OTYPER_OT11; // Configurar PC11 como salida push-pull
     GPIOC->OSPEEDR  &= ~ (GPIO_OSPEEDR_OSPEED11); // Configurar PC11 como baja velocidad
     GPIOC->PUPDR    &= ~ (GPIO_PUPDR_PUPD11); // Configurar PC11 sin pull-up/pull-down
     GPIOC->ODR      |= (GPIO_ODR_OD11); // Inicializar PC11 en alto (segmento apagado)

    /*
    d (PC10)
    */
     GPIOC->MODER    &= ~ (GPIO_MODER_MODE10); // Limpiar bits de modo para PC10
     GPIOC->MODER    |=  (GPIO_MODER_MODE10_0); // Configurar PC10 como salida (general purpose output)
     GPIOC->OTYPER   &= ~ GPIO_OTYPER_OT10; // Configurar PC10 como salida push-pull
     GPIOC->OSPEEDR  &= ~ (GPIO_OSPEEDR_OSPEED10); // Configurar PC10 como baja velocidad
     GPIOC->PUPDR    &= ~ (GPIO_PUPDR_PUPD10); // Configurar PC10 sin pull-up/pull-down
     GPIOC->ODR      |= (GPIO_ODR_OD10); // Inicializar PC10 en alto (segmento apagado)

    /*
    e (PC12)
    */
     GPIOC->MODER    &= ~ (GPIO_MODER_MODE12); // Limpiar bits de modo para PC12
     GPIOC->MODER    |=  (GPIO_MODER_MODE12_0); // Configurar PC12 como salida (general purpose output)
     GPIOC->OTYPER   &= ~ GPIO_OTYPER_OT12; // Configurar PC12 como salida push-pull
     GPIOC->OSPEEDR  &= ~ (GPIO_OSPEEDR_OSPEED12); // Configurar PC12 como baja velocidad
     GPIOC->PUPDR    &= ~ (GPIO_PUPDR_PUPD12); // Configurar PC12 sin pull-up/pull-down
     GPIOC->ODR      |= (GPIO_ODR_OD12); // Inicializar PC12 en alto (segmento apagado)

    /*
    f (PA11)
    */
     GPIOA->MODER    &= ~ (GPIO_MODER_MODE11); // Limpiar bits de modo para PA11
     GPIOA->MODER    |=  (GPIO_MODER_MODE11_0); // Configurar PA11 como salida (general purpose output)
     GPIOA->OTYPER   &= ~ GPIO_OTYPER_OT11; // Configurar PA11 como salida push-pull
     GPIOA->OSPEEDR  &= ~ (GPIO_OSPEEDR_OSPEED11); // Configurar PA11 como baja velocidad
     GPIOA->PUPDR    &= ~ (GPIO_PUPDR_PUPD11); // Configurar PA11 sin pull-up/pull-down
     GPIOA->ODR      |= (GPIO_ODR_OD11); // Inicializar PA11 en alto (segmento apagado)

    /*
    g (PD2)
    */
     GPIOD->MODER    &= ~ (GPIO_MODER_MODE2); // Limpiar bits de modo para PD2
     GPIOD->MODER    |=  (GPIO_MODER_MODE2_0); // Configurar PD2 como salida (general purpose output)
     GPIOD->OTYPER   &= ~ GPIO_OTYPER_OT2; // Configurar PD2 como salida push-pull
     GPIOD->OSPEEDR  &= ~ (GPIO_OSPEEDR_OSPEED2); // Configurar PD2 como baja velocidad
     GPIOD->PUPDR    &= ~ (GPIO_PUPDR_PUPD2); // Configurar PD2 sin pull-up/pull-down
     GPIOD->ODR      |= (GPIO_ODR_OD2); // Inicializar PD2 en alto (segmento apagado)

    /* 
    CONFIGURAR LOS PINES DE LOS DIGITOS COMO SALIDA : 
    (Cada pin va a la base de un transistor PNP: con 0 el digito enciende)
    */

    /*
    Digito 1 (PC5)
    */
     GPIOC->MODER    &= ~ (GPIO_MODER_MODE5); // Limpiar bits de modo para PC5
     GPIOC->MODER    |=  (GPIO_MODER_MODE5_0); // Configurar PC5 como salida (general purpose output)
     GPIOC->OTYPER   &= ~ GPIO_OTYPER_OT5; // Configurar PC5 como salida push-pull
     GPIOC->OSPEEDR  &= ~ (GPIO_OSPEEDR_OSPEED5); // Configurar PC5 como baja velocidad
     GPIOC->PUPDR    &= ~ (GPIO_PUPDR_PUPD5); // Configurar PC5 sin pull-up/pull-down
     GPIOC->ODR      |= (GPIO_ODR_OD5); // Inicializar PC5 en alto (digito apagado)

    /*
    Digito 2 (PC6)
    */
     GPIOC->MODER    &= ~ (GPIO_MODER_MODE6); // Limpiar bits de modo para PC6
     GPIOC->MODER    |=  (GPIO_MODER_MODE6_0); // Configurar PC6 como salida (general purpose output)
     GPIOC->OTYPER   &= ~ GPIO_OTYPER_OT6; // Configurar PC6 como salida push-pull
     GPIOC->OSPEEDR  &= ~ (GPIO_OSPEEDR_OSPEED6); // Configurar PC6 como baja velocidad
     GPIOC->PUPDR    &= ~ (GPIO_PUPDR_PUPD6); // Configurar PC6 sin pull-up/pull-down
     GPIOC->ODR      |= (GPIO_ODR_OD6); // Inicializar PC6 en alto (digito apagado)

    /*
    Digito 3 (PC2)
    */
     GPIOC->MODER    &= ~ (GPIO_MODER_MODE2); // Limpiar bits de modo para PC2
     GPIOC->MODER    |=  (GPIO_MODER_MODE2_0); // Configurar PC2 como salida (general purpose output)
     GPIOC->OTYPER   &= ~ GPIO_OTYPER_OT2; // Configurar PC2 como salida push-pull
     GPIOC->OSPEEDR  &= ~ (GPIO_OSPEEDR_OSPEED2); // Configurar PC2 como baja velocidad
     GPIOC->PUPDR    &= ~ (GPIO_PUPDR_PUPD2); // Configurar PC2 sin pull-up/pull-down
     GPIOC->ODR      |= (GPIO_ODR_OD2); // Inicializar PC2 en alto (digito apagado)

    /*
    Digito 4 (PB7)
    */
     GPIOB->MODER    &= ~ (GPIO_MODER_MODE7); // Limpiar bits de modo para PB7
     GPIOB->MODER    |=  (GPIO_MODER_MODE7_0); // Configurar PB7 como salida (general purpose output)
     GPIOB->OTYPER   &= ~ GPIO_OTYPER_OT7; // Configurar PB7 como salida push-pull
     GPIOB->OSPEEDR  &= ~ (GPIO_OSPEEDR_OSPEED7); // Configurar PB7 como baja velocidad
     GPIOB->PUPDR    &= ~ (GPIO_PUPDR_PUPD7); // Configurar PB7 sin pull-up/pull-down
     GPIOB->ODR      |= (GPIO_ODR_OD7); // Inicializar PB7 en alto (digito apagado)

    /*
    CONFIGURAR EL LED DE ESTADO (PH1) COMO SALIDA
    */
     GPIOH->MODER    &= ~ (GPIO_MODER_MODE1); // Limpiar bits de modo para PH1
     GPIOH->MODER    |=  (GPIO_MODER_MODE1_0); // Configurar PH1 como salida (general purpose output)
     GPIOH->OTYPER   &= ~ GPIO_OTYPER_OT1; // Configurar PH1 como salida push-pull
     GPIOH->OSPEEDR  &= ~ (GPIO_OSPEEDR_OSPEED1); // Configurar PH1 como baja velocidad
     GPIOH->PUPDR    &= ~ (GPIO_PUPDR_PUPD1); // Configurar PH1 sin pull-up/pull-down
     GPIOH->ODR      &= ~ (GPIO_ODR_OD1); // Inicializar PH1 en bajo (LED apagado)

    /*
     CONFIGURAR LOS SENSORES PC3 Y PA0 COMO ENTRADA
    (la resistencia de 10k ya esta en el protoboard)
    */

    /*
    Sensor que sube (PC3)
    */
     GPIOC->MODER    &= ~ (GPIO_MODER_MODE3); // Limpiar bits de modo para PC3 (00 = entrada)
     GPIOC->PUPDR    &= ~ (GPIO_PUPDR_PUPD3); // Configurar PC3 sin pull-up/pull-down

    /*
    Sensor que baja (PA0)
    */
     GPIOA->MODER    &= ~ (GPIO_MODER_MODE0); // Limpiar bits de modo para PA0 (00 = entrada)
     GPIOA->PUPDR    &= ~ (GPIO_PUPDR_PUPD0); // Configurar PA0 sin pull-up/pull-down

    /* 
     CONFIGURAR LAS INTERRUPCIONES EXTERNAS EXTI3 (PC3) Y EXTI0 (PA0)
    */

     SYSCFG->EXTICR[0] &= ~ (SYSCFG_EXTICR1_EXTI3); // Limpiar la seleccion de puerto de la linea EXTI3
     SYSCFG->EXTICR[0] |= (SYSCFG_EXTICR1_EXTI3_PC); // Conectar la linea EXTI3 al puerto C (0010 = PC3)
     SYSCFG->EXTICR[0] &= ~ (SYSCFG_EXTICR1_EXTI0); // Conectar la linea EXTI0 al puerto A (0000 = PA0)

     EXTI->IMR  |= (EXTI_IMR_MR3); // Habilitar la interrupcion de la linea 3
     EXTI->IMR  |= (EXTI_IMR_MR0); // Habilitar la interrupcion de la linea 0

     // Sensor que sube (PC3, linea 3): FLANCO DE SUBIDA
     EXTI->FTSR &= ~ (EXTI_FTSR_TR3); // Deshabilitar flanco de bajada en la linea 3
     EXTI->RTSR |= (EXTI_RTSR_TR3); // Habilitar flanco de subida en la linea 3

     // Sensor que baja (PA0, linea 0): FLANCO DE BAJADA
     EXTI->RTSR &= ~ (EXTI_RTSR_TR0); // Deshabilitar flanco de subida en la linea 0
     EXTI->FTSR |= (EXTI_FTSR_TR0); // Habilitar flanco de bajada en la linea 0

     EXTI->PR = (EXTI_PR_PR3 | EXTI_PR_PR0); // Limpiar banderas pendientes antes de habilitar

     NVIC_EnableIRQ(EXTI3_IRQn); // Habilitar la interrupcion EXTI3 en el NVIC
     NVIC_EnableIRQ(EXTI0_IRQn); // Habilitar la interrupcion EXTI0 en el NVIC

    /* 
     CONFIGURAR TIM2 PARA EL BLINKY (INTERRUPCION CADA 500 ms)
     Reloj del timer = 16 MHz
     PSC = 16000 - 1  -> el contador avanza cada 1 ms (16 MHz / 16000 = 1 kHz)
     ARR = 500 - 1    -> desborda cada 500 ms
    */

     TIM2->CR1  &= ~ (TIM_CR1_CEN); // Detener TIM2 mientras se configura
     TIM2->CR1  &= ~ (TIM_CR1_DIR); // Contar hacia arriba
     TIM2->PSC  = 16000 - 1; // Preescaler: 1 cuenta = 1 ms
     TIM2->ARR  = 500 - 1; // Auto-recarga: interrupcion cada 500 ms
     TIM2->CNT  = 0; // Reiniciar la cuenta
     TIM2->EGR  |= (TIM_EGR_UG); // Generar un evento de actualizacion para cargar el PSC
     TIM2->SR   &= ~ (TIM_SR_UIF); // Limpiar la bandera que deja el evento de actualizacion
     TIM2->DIER |= (TIM_DIER_UIE); // Habilitar la interrupcion por desborde (update)

     NVIC_EnableIRQ(TIM2_IRQn); // Habilitar la interrupcion de TIM2 en el NVIC

     TIM2->CR1  |= (TIM_CR1_CEN); // Arrancar TIM2

    /*
     CONFIGURAR TIM3 PARA EL REFRESCO DEL DISPLAY (INTERRUPCION CADA 1 ms)
     Reloj del timer = 16 MHz
     PSC = 16 - 1     -> el contador avanza cada 1 us (16 MHz / 16 = 1 MHz)
     ARR = 1000 - 1   -> desborda cada 1 ms
    */
     TIM3->CR1  &= ~ (TIM_CR1_CEN); // Detener TIM3 mientras se configura
     TIM3->CR1  &= ~ (TIM_CR1_DIR); // Contar hacia arriba
     TIM3->PSC  = 16 - 1; // Preescaler: 1 cuenta = 1 us
     TIM3->ARR  = 1000 - 1; // Auto-recarga: interrupcion cada 1 ms
     TIM3->CNT  = 0; // Reiniciar la cuenta
     TIM3->EGR  |= (TIM_EGR_UG); // Generar un evento de actualizacion para cargar el PSC
     TIM3->SR   &= ~ (TIM_SR_UIF); // Limpiar la bandera que deja el evento de actualizacion
     TIM3->DIER |= (TIM_DIER_UIE); // Habilitar la interrupcion por desborde (update)

     NVIC_EnableIRQ(TIM3_IRQn); // Habilitar la interrupcion de TIM3 en el NVIC

     TIM3->CR1  |= (TIM_CR1_CEN); // Arrancar TIM3

    /* 
    BUCLE PRINCIPAL
    Aqui se atienden las banderas que levantan las interrupciones
    */
    while (1)
    {
        /*
        TIM2 -> BLINKY
        */
        if (bandera_blinky == 1)
        {
            bandera_blinky = 0; // Bajar la bandera
            GPIOH->ODR ^= (GPIO_ODR_OD1); // Invertir PH1 (si estaba prendido se apaga y viceversa)
        }

        /*
        EXTI3 -> SENSOR QUE SUBE (PC3)
        */
        if (bandera_sube == 1)
        {
            bandera_sube = 0; // Bajar la bandera
            if ((milisegundos - ultimo_subir) >= 50) // Antirrebote: ignorar pulsos a menos de 50 ms
            {
                ultimo_subir = milisegundos;
                contador ++; // Sin proteccion: despues de 65535 vuelve a 0
            }
        }

        /*
        EXTI0 -> SENSOR QUE BAJA (PA0)
        */
        if (bandera_baja == 1)
        {
            bandera_baja = 0; // Bajar la bandera
            if ((milisegundos - ultimo_bajar) >= 50) // Antirrebote: ignorar pulsos a menos de 50 ms
            {
                ultimo_bajar = milisegundos;
                contador --; // Sin proteccion: de 0 pasa a 65535 (uint16_t) y en el display se ve 5535
            }
        }

        /*
        TIM3 -> REFRESCO DEL DISPLAY (MULTIPLEXADO)
        */
        if (bandera_display == 1)
        {
            bandera_display = 0; // Bajar la bandera
            milisegundos ++; // Paso 1 ms (lo usa el antirrebote de los sensores)

            // Apagar todos los digitos antes de cambiar los segmentos (evita fantasmas)
            GPIOC->ODR |= (GPIO_ODR_OD5 | GPIO_ODR_OD6 | GPIO_ODR_OD2); // Apagar digitos 1, 2 y 3
            GPIOB->ODR |= (GPIO_ODR_OD7); // Apagar digito 4

            // Separar la cifra que corresponde al digito actual
            switch (estado_actual)
            {
                case 0:
                    cifra = (contador / 1000) % 10; // Unidades de mil (el % 10 descarta las decenas de mil: 65535 -> 5)
                    break;

                case 1:
                    cifra = (contador / 100) % 10; // Centenas
                    break;

                case 2:
                    cifra = (contador / 10) % 10; // Decenas
                    break;

                case 3:
                    cifra = contador % 10; // Unidades
                    break;

                default:
                    cifra = 0;
                    break;
            }

            // Apagar todos los segmentos (en anodo comun se apagan con 1)
            GPIOB->ODR |= (GPIO_ODR_OD12); // Apagar a
            GPIOA->ODR |= (GPIO_ODR_OD12 | GPIO_ODR_OD11); // Apagar b y f
            GPIOC->ODR |= (GPIO_ODR_OD11 | GPIO_ODR_OD10 | GPIO_ODR_OD12); // Apagar c, d y e
            GPIOD->ODR |= (GPIO_ODR_OD2); // Apagar g

            // Encender los segmentos de la cifra (en anodo comun se encienden con 0)
            switch (cifra)
            {
                case 0: // a b c d e f
                    GPIOB->ODR &= ~(GPIO_ODR_OD12); // Encender a
                    GPIOA->ODR &= ~(GPIO_ODR_OD12); // Encender b
                    GPIOC->ODR &= ~(GPIO_ODR_OD11); // Encender c
                    GPIOC->ODR &= ~(GPIO_ODR_OD10); // Encender d
                    GPIOC->ODR &= ~(GPIO_ODR_OD12); // Encender e
                    GPIOA->ODR &= ~(GPIO_ODR_OD11); // Encender f
                    break;

                case 1: // b c
                    GPIOA->ODR &= ~(GPIO_ODR_OD12); // Encender b
                    GPIOC->ODR &= ~(GPIO_ODR_OD11); // Encender c
                    break;

                case 2: // a b d e g
                    GPIOB->ODR &= ~(GPIO_ODR_OD12); // Encender a
                    GPIOA->ODR &= ~(GPIO_ODR_OD12); // Encender b
                    GPIOC->ODR &= ~(GPIO_ODR_OD10); // Encender d
                    GPIOC->ODR &= ~(GPIO_ODR_OD12); // Encender e
                    GPIOD->ODR &= ~(GPIO_ODR_OD2);  // Encender g
                    break;

                case 3: // a b c d g
                    GPIOB->ODR &= ~(GPIO_ODR_OD12); // Encender a
                    GPIOA->ODR &= ~(GPIO_ODR_OD12); // Encender b
                    GPIOC->ODR &= ~(GPIO_ODR_OD11); // Encender c
                    GPIOC->ODR &= ~(GPIO_ODR_OD10); // Encender d
                    GPIOD->ODR &= ~(GPIO_ODR_OD2);  // Encender g
                    break;

                case 4: // b c f g
                    GPIOA->ODR &= ~(GPIO_ODR_OD12); // Encender b
                    GPIOC->ODR &= ~(GPIO_ODR_OD11); // Encender c
                    GPIOA->ODR &= ~(GPIO_ODR_OD11); // Encender f
                    GPIOD->ODR &= ~(GPIO_ODR_OD2);  // Encender g
                    break;

                case 5: // a c d f g
                    GPIOB->ODR &= ~(GPIO_ODR_OD12); // Encender a
                    GPIOC->ODR &= ~(GPIO_ODR_OD11); // Encender c
                    GPIOC->ODR &= ~(GPIO_ODR_OD10); // Encender d
                    GPIOA->ODR &= ~(GPIO_ODR_OD11); // Encender f
                    GPIOD->ODR &= ~(GPIO_ODR_OD2);  // Encender g
                    break;

                case 6: // a c d e f g
                    GPIOB->ODR &= ~(GPIO_ODR_OD12); // Encender a
                    GPIOC->ODR &= ~(GPIO_ODR_OD11); // Encender c
                    GPIOC->ODR &= ~(GPIO_ODR_OD10); // Encender d
                    GPIOC->ODR &= ~(GPIO_ODR_OD12); // Encender e
                    GPIOA->ODR &= ~(GPIO_ODR_OD11); // Encender f
                    GPIOD->ODR &= ~(GPIO_ODR_OD2);  // Encender g
                    break;

                case 7: // a b c
                    GPIOB->ODR &= ~(GPIO_ODR_OD12); // Encender a
                    GPIOA->ODR &= ~(GPIO_ODR_OD12); // Encender b
                    GPIOC->ODR &= ~(GPIO_ODR_OD11); // Encender c
                    break;

                case 8: // a b c d e f g
                    GPIOB->ODR &= ~(GPIO_ODR_OD12); // Encender a
                    GPIOA->ODR &= ~(GPIO_ODR_OD12); // Encender b
                    GPIOC->ODR &= ~(GPIO_ODR_OD11); // Encender c
                    GPIOC->ODR &= ~(GPIO_ODR_OD10); // Encender d
                    GPIOC->ODR &= ~(GPIO_ODR_OD12); // Encender e
                    GPIOA->ODR &= ~(GPIO_ODR_OD11); // Encender f
                    GPIOD->ODR &= ~(GPIO_ODR_OD2);  // Encender g
                    break;

                case 9: // a b c d f g
                    GPIOB->ODR &= ~(GPIO_ODR_OD12); // Encender a
                    GPIOA->ODR &= ~(GPIO_ODR_OD12); // Encender b
                    GPIOC->ODR &= ~(GPIO_ODR_OD11); // Encender c
                    GPIOC->ODR &= ~(GPIO_ODR_OD10); // Encender d
                    GPIOA->ODR &= ~(GPIO_ODR_OD11); // Encender f
                    GPIOD->ODR &= ~(GPIO_ODR_OD2);  // Encender g
                    break;

                default:
                    break; // Cifra invalida: el digito queda apagado
            }

            // Encender el digito actual y pasar al siguiente estado
            switch (estado_actual)
            {
                case 0:
                    GPIOC->ODR &= ~(GPIO_ODR_OD5); // Encender digito 1 (PC5)
                    estado_actual ++;
                    break;

                case 1:
                    GPIOC->ODR &= ~(GPIO_ODR_OD6); // Encender digito 2 (PC6)
                    estado_actual ++;
                    break;

                case 2:
                    GPIOC->ODR &= ~(GPIO_ODR_OD2); // Encender digito 3 (PC2)
                    estado_actual ++;
                    break;

                case 3:
                    GPIOB->ODR &= ~(GPIO_ODR_OD7); // Encender digito 4 (PB7)
                    estado_actual = 0;
                    break;

                default:
                    estado_actual = 0;
                    break;
            }
        }
    }

    return 0;
}

/*
 CALLBACKS: SOLO LEVANTAN LA BANDERA, EL TRABAJO SE HACE EN EL WHILE
*/

void callback_blinky(void)
{
    bandera_blinky = 1; // Avisar al while que toca invertir el LED de estado
}

void callback_display(void)
{
    bandera_display = 1; // Avisar al while que toca refrescar el siguiente digito
}

void callback_sensor_sube(void)
{
    bandera_sube = 1; // Avisar al while que el sensor de PC3 detecto un objeto
}

void callback_sensor_baja(void)
{
    bandera_baja = 1; // Avisar al while que el sensor de PA0 detecto un objeto
}

/* 
 RUTINAS DE INTERRUPCION (IRQHandlers)
 Cada una verifica su bandera, la limpia y llama a su callback
*/

void TIM2_IRQHandler(void)
{
    if (TIM2->SR & TIM_SR_UIF) // Verificar si la interrupcion fue por desborde de TIM2
    {
        TIM2->SR &= ~ (TIM_SR_UIF); // Limpiar la bandera (se limpia escribiendo 0)
        callback_blinky();
    }
}

void TIM3_IRQHandler(void)
{
    if (TIM3->SR & TIM_SR_UIF) // Verificar si la interrupcion fue por desborde de TIM3
    {
        TIM3->SR &= ~ (TIM_SR_UIF); // Limpiar la bandera (se limpia escribiendo 0)
        callback_display();
    }
}

void EXTI3_IRQHandler(void)
{
    if (EXTI->PR & EXTI_PR_PR3) // Verificar si la interrupcion fue por PC3
    {
        EXTI->PR |= EXTI_PR_PR3; // Limpiar la bandera (se limpia escribiendo 1)
        callback_sensor_sube();
    }
}

void EXTI0_IRQHandler(void)
{
    if (EXTI->PR & EXTI_PR_PR0) // Verificar si la interrupcion fue por PA0
    {
        EXTI->PR |= EXTI_PR_PR0; // Limpiar la bandera (se limpia escribiendo 1)
        callback_sensor_baja();
    }
}